const motion=matchMedia('(prefers-reduced-motion: reduce)');
function dust(){const layer=document.querySelector('.dust');layer.replaceChildren();if(motion.matches)return;for(let i=0;i<35;i++){const p=document.createElement('i');p.style.left=`${Math.random()*100}%`;p.style.animationDuration=`${10+Math.random()*15}s`;p.style.animationDelay=`-${Math.random()*25}s`;layer.append(p)}}dust();motion.addEventListener('change',dust);
let last=0;document.addEventListener('pointermove',e=>{if(motion.matches||e.pointerType!=='mouse'||performance.now()-last<90)return;last=performance.now();const s=document.createElement('span');s.className='trail';s.textContent='✧';s.style.left=`${e.clientX}px`;s.style.top=`${e.clientY}px`;s.setAttribute('aria-hidden','true');document.body.append(s);setTimeout(()=>s.remove(),750)});
